// 回溯：從 start 開始選，同一個數可重複選（遞迴時仍傳 i）
// 時間複雜度: O(2^target) 量級，空間複雜度: O(target)
static int cmp(const void* a, const void* b) { return *(const int*)a - *(const int*)b; }

static int** result;
static int* colSizes;
static int count, cap;
static int path[64], pathLen;

static void backtrack(int* cand, int n, int start, int remain) {
    if (remain == 0) {
        if (count == cap) {
            cap *= 2;
            result = realloc(result, sizeof(int*) * cap);
            colSizes = realloc(colSizes, sizeof(int) * cap);
        }
        result[count] = malloc(sizeof(int) * pathLen);
        memcpy(result[count], path, sizeof(int) * pathLen);
        colSizes[count++] = pathLen;
        return;
    }
    for (int i = start; i < n && cand[i] <= remain; i++) {   // 已排序可剪枝
        path[pathLen++] = cand[i];
        backtrack(cand, n, i, remain - cand[i]);
        pathLen--;
    }
}

int** combinationSum(int* candidates, int candidatesSize, int target,
                     int* returnSize, int** returnColumnSizes) {
    qsort(candidates, candidatesSize, sizeof(int), cmp);
    cap = 16; count = 0; pathLen = 0;
    result = malloc(sizeof(int*) * cap);
    colSizes = malloc(sizeof(int) * cap);
    backtrack(candidates, candidatesSize, 0, target);
    *returnSize = count;
    *returnColumnSizes = colSizes;
    return result;
}

